#include <stdlib.h>

/* The original strdup operation calls this Nintendo allocator entry point.
 * Its declaration is recorded in curl_nintendo_allocator.c's DWARF.
 */
extern char *Curl_SigloStrdup(const char *string);

/* Upstream curl-7_50_3 getenv.c, with the target's non-Windows configuration. */
static char *GetEnv(const char *variable)
{
  char *env = getenv(variable);
  return (env && env[0]) ? Curl_SigloStrdup(env) : NULL;
}

char *curl_getenv(const char *v)
{
  return GetEnv(v);
}

